// Throwaway. Verifies every DSLD id in CATALOG_BRANDED_176.md against
// https://api.ods.od.nih.gov/dsld/v9/label/<id> and writes .verify-dsld.json.
// Deleted before the commit — nothing in the repo depends on it.
import fs from 'node:fs';

const md = fs.readFileSync('CATALOG_BRANDED_176.md', 'utf8');
const lines = md.split(/\r?\n/);

const rows = [];
let section = null;
for (const line of lines) {
  const h = line.match(/^# (.+)$/);
  if (h) { section = h[1].trim(); continue; }
  const m = line.match(/^\|\s*([^|]+?)\s*\|\s*([^|]+?)\s*\|\s*([^|]+?)\s*\|\s*(\d+)\s*\|$/);
  if (!m) continue;
  rows.push({ section, brand: m[1], product: m[2], form: m[3], id: Number(m[4]) });
}
console.log(`parsed ${rows.length} rows across ${new Set(rows.map((r) => r.section)).size} sections`);

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function fetchLabel(id, attempt = 0) {
  try {
    const res = await fetch(`https://api.ods.od.nih.gov/dsld/v9/label/${id}`, {
      headers: { accept: 'application/json' },
      signal: AbortSignal.timeout(30000),
    });
    if (res.status === 404) return { ok: false, reason: 'http 404' };
    if (!res.ok) throw new Error(`http ${res.status}`);
    return { ok: true, body: await res.json() };
  } catch (e) {
    if (attempt < 3) { await sleep(1500 * (attempt + 1)); return fetchLabel(id, attempt + 1); }
    return { ok: false, reason: String(e.message || e) };
  }
}

const out = [];
for (let i = 0; i < rows.length; i++) {
  const r = rows[i];
  const res = await fetchLabel(r.id);
  if (!res.ok) {
    out.push({ ...r, resolved: false, reason: res.reason });
    console.log(`${i + 1}/${rows.length} ${r.id} FAILED ${res.reason}`);
  } else {
    const b = res.body;
    out.push({
      ...r,
      resolved: true,
      apiBrand: b.brandName ?? '',
      apiName: b.fullName ?? '',
      apiForm: (b.physicalState && (b.physicalState.langualDesc || b.physicalState.name)) || '',
      offMarket: b.offMarket ?? null,
      statusHistory: b.statusHistory ?? null,
      productType: (b.productType && (b.productType.langualDesc || b.productType.name)) || '',
      netContents: b.netContents ?? null,
      entryDate: b.entryDate ?? null,
    });
    console.log(`${i + 1}/${rows.length} ${r.id} ok  ${b.brandName} | ${b.fullName}`);
  }
  await sleep(120);
}

fs.writeFileSync('.verify-dsld.json', JSON.stringify(out, null, 2));
console.log(`\nresolved: ${out.filter((o) => o.resolved).length}/${out.length}`);

