input.command:
node -e "
const fs=require('fs');
const d=JSON.parse(fs.readFileSync('.verify-dsld.json','utf8'));
const norm=s=>String(s||'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
let brandDiff=0,nameDiff=0;
console.log('--- BRAND mismatches ---');
for(const r of d){ if(norm(r.brand)!==norm(r.apiBrand)){brandDiff++;console.log(r.id,'| file:',r.brand,'| api:',r.apiBrand);} }
console.log('--- NAME mismatches ---');
for(const r of d){ if(norm(r.product)!==norm(r.apiName)){nameDiff++;console.log(r.id,'| file:',r.product,'|| api:',r.apiName);} }
console.log('brandDiff',brandDiff,'nameDiff',nameDiff);
console.log('--- offMarket values ---', JSON.stringify([...new Set(d.map(r=>JSON.stringify(r.offMarket)))]));
console.log('--- dup ids ---', d.length, new Set(d.map(r=>r.id)).size);
"

