// Throwaway. Applies migration 0020's slug rule to the 176 rows and checks
// them against each other and against the 74 renamed slugs 0020 produces.
import fs from 'node:fs';

const slugify = (s) =>
  String(s)
    .toLowerCase()
    .replace(/'/g, '')
    .replace(/’/g, '')
    .replace(/\.(com|co|net)\b/g, '')
    .replace(/&/g, ' and ')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');

const rows = JSON.parse(fs.readFileSync('.verify-dsld.json', 'utf8'));
const withSlug = rows.map((r) => ({ ...r, slug: `${slugify(r.brand)}-${slugify(r.product)}` }));

const existing = new Set(
  [...fs.readFileSync('supabase/migrations/0020_product_shaped_slugs.sql', 'utf8')
    .matchAll(/\('([a-z0-9-]+)',\s*'([a-z0-9-]+)'\)/g)].map((m) => m[2]),
);
console.log('0020 target slugs:', existing.size);

const seen = new Map();
for (const r of withSlug) {
  if (seen.has(r.slug)) console.log('DUP within 176:', r.slug, r.id, seen.get(r.slug));
  else seen.set(r.slug, r.id);
  if (existing.has(r.slug)) console.log('COLLIDES with an existing row:', r.slug, r.id);
}
console.log('distinct new slugs:', seen.size, 'of', withSlug.length);
console.log('longest:', withSlug.map((r) => r.slug).sort((a, b) => b.length - a.length)[0]);
console.log('\nforms in the file:', JSON.stringify([...new Set(withSlug.map((r) => r.form))]));
console.log('\nsections:');
for (const s of new Set(withSlug.map((r) => r.section)))
  console.log(' ', s, withSlug.filter((r) => r.section === s).length);

fs.writeFileSync('.slugs.json', JSON.stringify(withSlug, null, 2));

