// Throwaway. Pulls the ingredient panel for each verified label so the
// mechanism sentences in the migration describe what the label actually
// declares. Deleted before the commit.
import fs from 'node:fs';

const rows = JSON.parse(fs.readFileSync('.slugs.json', 'utf8'));
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function get(id, attempt = 0) {
  try {
    const res = await fetch(`https://api.ods.od.nih.gov/dsld/v9/label/${id}`, {
      headers: { accept: 'application/json' },
      signal: AbortSignal.timeout(30000),
    });
    if (!res.ok) throw new Error(`http ${res.status}`);
    return await res.json();
  } catch (e) {
    if (attempt < 3) { await sleep(1500 * (attempt + 1)); return get(id, attempt + 1); }
    throw e;
  }
}

const out = {};
for (let i = 0; i < rows.length; i++) {
  const r = rows[i];
  const b = await get(r.id);
  const flat = [];
  const walk = (list) => {
    for (const ing of list ?? []) {
      flat.push(ing.name);
      if (ing.nestedRows) walk(ing.nestedRows);
    }
  };
  walk(b.ingredientRows);
  out[r.id] = {
    slug: r.slug,
    name: `${r.brand} ${r.product}`,
    form: r.form,
    physicalState: b.physicalState?.langualDesc ?? '',
    statements: (b.statements ?? []).map((s) => `${s.type}: ${s.notes}`).slice(0, 4),
    ingredients: flat.slice(0, 40),
  };
  console.log(`${i + 1}/${rows.length} ${r.id} ${flat.length} ingredients`);
  await sleep(110);
}

fs.writeFileSync('.ingredients.json', JSON.stringify(out, null, 2));

