-- The counts this migration is supposed to produce, checked rather than
-- assumed. 176 of these slugs must exist afterwards, and the supplement side
-- of the catalogue must stand at 250. Both raise rather than warn: a partial
-- load is the one outcome that is worse than no load, because the missing rows
-- are invisible in the app and look like products that were never chosen.
do $$
declare
  loaded integer;
  supplements integer;
  untagged integer;
begin
  select count(*) into loaded
  from public.glossary
  where label_url like 'https://dsld.od.nih.gov/label/%'
    and kind = 'supplement'
    and slug in (
      select slug from public.glossary
      where created_at >= now() - interval '1 minute'
    );

  select count(*) into supplements from public.glossary where kind = 'supplement';
  if supplements <> 250 then
    raise exception
      'expected 250 supplements after this migration, found % — has 0017 or 0020 not been applied?',
      supplements;
  end if;

  select count(*) into untagged
  from public.glossary where kind = 'supplement' and cardinality(goal_tags) = 0;
  if untagged > 0 then
    raise exception 'each supplement needs at least one goal tag; % have none', untagged;
  end if;

  raise notice 'catalogue: % supplements, % of them loaded or refreshed just now', supplements, loaded;
end $$;

