// Throwaway. Two checks on the generated migration: that the SQL is
// well-formed (row count, arity, quote balance), and that the rules in
// src/lib/recommend.ts fire on the new rows the way they are meant to.
import fs from 'node:fs';

const sql = fs.readFileSync('supabase/migrations/0021_catalogue_176.sql', 'utf8');

/* ── SQL shape ─────────────────────────────────────────────────────────── */

// strip comments, then tokenise on quotes to find the values tuples
const noComments = sql.split('\n').filter((l) => !l.trimStart().startsWith('--')).join('\n');
const quotes = (noComments.match(/'/g) ?? []).length;
console.log('single quotes:', quotes, quotes % 2 === 0 ? 'balanced' : 'UNBALANCED');

const body = noComments.slice(noComments.indexOf('values\n') + 7, noComments.indexOf('on conflict'));
// split tuples at "),\n  (" boundaries at the start of a line
const tuples = body.split(/\),\n\s*\(/).map((t) => t.replace(/^\s*\(/, '').replace(/\)\s*$/, ''));
console.log('tuples:', tuples.length);

const splitTop = (s) => {
  const parts = [];
  let depth = 0, inStr = false, cur = '';
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (inStr) {
      if (c === "'") { if (s[i + 1] === "'") { cur += "''"; i++; continue; } inStr = false; }
      cur += c; continue;
    }
    if (c === "'") { inStr = true; cur += c; continue; }
    if (c === '[' || c === '(') depth++;
    if (c === ']' || c === ')') depth--;
    if (c === ',' && depth === 0) { parts.push(cur.trim()); cur = ''; continue; }
    cur += c;
  }
  parts.push(cur.trim());
  return parts;
};

const bad = [];
const parsed = [];
for (const t of tuples) {
  const cols = splitTop(t);
  if (cols.length !== 13) bad.push([cols.length, cols[0]]);
  const unq = (v) => v.replace(/^'|'$/g, '').replace(/''/g, "'");
  const arrOf = (v) =>
    v === "'{}'::text[]" ? [] : [...v.matchAll(/'((?:[^']|'')*)'/g)].map((m) => m[1].replace(/''/g, "'"));
  parsed.push({
    slug: unq(cols[0]), name: unq(cols[1]), category: unq(cols[2]),
    mech: unq(cols[3]), store: unq(cols[4]), route: unq(cols[5]), research: unq(cols[6]),
    goal_tags: arrOf(cols[7]), search_keywords: arrOf(cols[8]),
    kind: unq(cols[9]), brand: unq(cols[10]), product_form: unq(cols[11]), label_url: unq(cols[12]),
  });
}
if (bad.length) console.log('WRONG ARITY:', bad);
else console.log('every tuple has 13 columns');

const CATS = ['healing', 'growth', 'cosmetic', 'cognitive', 'other'];
const TAGS = ['Skin','Sleep','Energy','Focus','Muscle','Recovery','Immune','Gut Health','Mood','Anti-Aging','Injury'];
for (const p of parsed) {
  if (!CATS.includes(p.category)) console.log('BAD CATEGORY', p.slug, p.category);
  if (p.route !== 'oral') console.log('BAD ROUTE', p.slug);
  if (p.kind !== 'supplement') console.log('BAD KIND', p.slug);
  if (!p.goal_tags.length) console.log('NO TAGS', p.slug);
  for (const t of p.goal_tags) if (!TAGS.includes(t)) console.log('UNKNOWN TAG', p.slug, t);
  if (!/^https:\/\/dsld\.od\.nih\.gov\/label\/\d+$/.test(p.label_url)) console.log('BAD URL', p.slug);
  if (!p.name.startsWith(p.brand)) console.log('NAME NOT BRAND-PREFIXED', p.slug);
}
const slugs = new Set(parsed.map((p) => p.slug));
console.log('distinct slugs:', slugs.size);

// apostrophes survived the escaping
console.log("rows with an apostrophe in the name:",
  parsed.filter((p) => p.name.includes("'")).map((p) => p.name).join(' / '));

/* ── what the rules will do ────────────────────────────────────────────── */

const NUTRIENT = {
  b12: [/\bb-?12\b/, /cobalamin/],
  iron: [/\biron\b/, /ferrous/, /ferric/],
  zinc: [/\bzinc\b/],
  magnesium: [/\bmagnesium\b/],
  omega3: [/\bomega[\s-]?3\b/, /\bdha\b/, /\bepa\b/, /fish oil/, /\bkrill\b/, /cod liver/],
  calcium: [/\bcalcium\b/],
  vitaminD: [/\bvitamin\s?d\b/, /\bd-?3\b/, /cholecalciferol/],
  choline: [/choline/],
  niacin: [/niacin/, /nicotinamide/, /nicotinic/],
};
const textOf = (p) => `${p.name} ${p.slug} ${p.search_keywords.join(' ')}`.toLowerCase();
const hits = (t, terms) => terms.some((r) => r.test(t));

console.log('\n── nutrient groups the new rows land in ──');
for (const [k, terms] of Object.entries(NUTRIENT)) {
  const m = parsed.filter((p) => hits(textOf(p), terms));
  console.log(`${k} (${m.length}):`);
  for (const p of m) console.log('   ', p.name);
}

console.log('\n── swap outcomes ──');
const omega = parsed.filter((p) => hits(textOf(p), NUTRIENT.omega3));
const algal = omega.filter((p) => /algal|algae|vegan|schizochytrium/.test(textOf(p)));
console.log('omega-3 preferred (algal/vegan):', algal.map((p) => p.name));
console.log('omega-3 swapped out for no-fish:', omega.filter((p) => !algal.includes(p)).map((p) => p.name));

const mag = parsed.filter((p) => hits(textOf(p), NUTRIENT.magnesium));
console.log('magnesium preferred (glycinate):', mag.filter((p) => /glycinate/.test(textOf(p))).map((p) => p.name));
console.log('magnesium avoided (citrate/oxide):', mag.filter((p) => /citrate|oxide/.test(textOf(p))).map((p) => p.name));

const b3 = parsed.filter((p) => hits(textOf(p), NUTRIENT.niacin));
console.log('B3 preferred (niacinamide):', b3.filter((p) => /niacinamide|nicotinamide/.test(textOf(p))).map((p) => p.name));
console.log('B3 avoided (nicotinic):', b3.filter((p) => /\bniacin\b|nicotinic/.test(textOf(p))).map((p) => p.name));

/* ── form classification ───────────────────────────────────────────────── */
const classify = (f0) => {
  const f = (f0 ?? '').toLowerCase();
  if (!f) return 'other';
  if (f.includes('gummy') || f.includes('gummies') || f.includes('chew')) return 'gummy';
  if (f.includes('softgel') || f.includes('soft gel')) return 'softgel';
  if (f.includes('capsule')) return 'capsule';
  if (f.includes('tablet') || f.includes('caplet')) return 'tablet';
  if (f.includes('powder')) return 'powder';
  if (f.includes('liquid') || f.includes('drops') || f.includes('tincture') || f.includes('oil')) return 'liquid';
  return 'other';
};
const byClass = {};
for (const p of parsed) {
  const c = classify(p.product_form);
  (byClass[c] ??= []).push(p.product_form);
}
console.log('\n── form classes ──');
for (const [c, fs_] of Object.entries(byClass)) {
  const counts = {};
  for (const f of fs_) counts[f] = (counts[f] ?? 0) + 1;
  console.log(c, JSON.stringify(counts));
}

